def accounts_merge_brute(accounts):
    groups = [set(acc[1:]) for acc in accounts]
    names = [acc[0] for acc in accounts]
    changed = True
    while changed:
        changed = False
        for i in range(len(groups)):
            for j in range(i + 1, len(groups)):
                if groups[i] and groups[j] and groups[i] & groups[j]:      # share ANY email
                    groups[i] |= groups[j]
                    groups[j] = set()                                        # merged away
                    changed = True
    return [[names[i]] + sorted(groups[i]) for i in range(len(groups)) if groups[i]]

