def accounts_merge(accounts):
    parent = {}
    email_to_name = {}
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
    for acc in accounts:
        name = acc[0]
        for email in acc[1:]:
            if email not in parent:
                parent[email] = email
            email_to_name[email] = name
            if email != acc[1]:
                union(acc[1], email)                              # union within the SAME account
    groups = {}
    for email in parent:
        root = find(email)
        groups.setdefault(root, []).append(email)
    return [[email_to_name[root]] + sorted(emails) for root, emails in groups.items()]

